import React, { useState } from 'react';
import './App.css';

function App() {
  const [productId, setProductId] = useState('');
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState(null);
  const [error, setError] = useState('');

  const handleAnalyze = async () => {
    if (!productId.trim()) {
      setError('Please enter a product ID');
      return;
    }

    setLoading(true);
    setError('');

    try {
      // Сначала получаем список изображений для продукта
      const imagesResponse = await fetch(`http://localhost:5002/product-images/${productId.trim()}`);
      const imagesData = await imagesResponse.json();

      // Затем анализируем продукт
      const analyzeResponse = await fetch('http://localhost:5002/analyze-product', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ product_id: productId.trim() }),
      });

      const data = await analyzeResponse.json();

      if (!analyzeResponse.ok) {
        throw new Error(data.error || 'Failed to process product');
      }

      // Объединяем данные для отображения
      const combinedResults = {
        ...data,
        imagesInfo: imagesData
      };

      setResults(combinedResults);
    } catch (err) {
      setError(err.message || 'An error occurred while processing the request');
    } finally {
      setLoading(false);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter') {
      handleAnalyze();
    }
  };

  // Компонент для отображения изображения с информацией о найденных объектах
  const ImageViewWithDetails = ({ imageInfo, imageFeatures, index }) => {
    // Функция для преобразования координат bounding box в стили CSS
    const getBoundingBoxStyle = (bbox, imgWidth, imgHeight) => {
      if (!bbox || !imgWidth || !imgHeight) return {};

      // Преобразуем координаты в пиксели
      const xMin = (bbox.x_min / 100) * imgWidth;
      const yMin = (bbox.y_min / 100) * imgHeight;
      const xMax = (bbox.x_max / 100) * imgWidth;
      const yMax = (bbox.y_max / 100) * imgHeight;

      // Вычисляем размеры прямоугольника
      const width = xMax - xMin;
      const height = yMax - yMin;

      return {
        position: 'absolute',
        left: `${xMin}px`,
        top: `${yMin}px`,
        width: `${width}px`,
        height: `${height}px`,
        border: '2px solid #4CAF50',
        backgroundColor: 'rgba(76, 175, 80, 0.1)',
        zIndex: 10,
        boxSizing: 'border-box'
      };
    };

    return (
      <div key={index} className="image-item">
        <div className="image-container">
          <div style={{ position: 'relative', display: 'inline-block' }}>
            <img
              src={`http://localhost:5002/images/${imageInfo.filename}`}
              alt={`Product ${index + 1}`}
              onError={(e) => {
                e.target.src = 'https://via.placeholder.com/300?text=Image+Not+Found';
              }}
              style={{ 
                maxWidth: '100%', 
                height: 'auto',
                display: 'block',
                position: 'relative'
              }}
              onLoad={(e) => {
                // Устанавливаем размеры контейнера при загрузке изображения
                e.target.style.width = '100%';
              }}
            />
            {/* Визуализация bounding boxes */}
            {imageFeatures && imageFeatures.length > 0 && imageFeatures.map((obj, objIndex) => {
              // Предполагаем, что мы можем получить размеры изображения через емулляцию
              const bboxStyle = obj.bbox ? {
                position: 'absolute',
                left: `${obj.bbox.x_min}%`,
                top: `${obj.bbox.y_min}%`,
                width: `${obj.bbox.x_max - obj.bbox.x_min}%`,
                height: `${obj.bbox.y_max - obj.bbox.y_min}%`,
                border: '2px solid #4CAF50',
                backgroundColor: 'rgba(76, 175, 80, 0.1)',
                zIndex: 10,
                boxSizing: 'border-box',
                display: 'flex',
                alignItems: 'flex-start',
                justifyContent: 'center'
              } : {};
              return (
                <div 
                  key={objIndex} 
                  style={bboxStyle}
                  className="bounding-box-overlay"
                >
                  {obj.name && (
                    <div 
                      style={{
                        position: 'absolute',
                        top: '-25px',
                        left: '0',
                        backgroundColor: '#4CAF50',
                        color: 'white',
                        padding: '2px 6px',
                        fontSize: '12px',
                        borderRadius: '2px',
                        zIndex: 11,
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        maxWidth: '100%'
                      }}
                    >
                      {obj.name}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
          <div className="image-info">
            <p>Order: {imageInfo.order}</p>
            <p>Filename: {imageInfo.filename}</p>
            <p>Status: {imageInfo.exists ? '✓ Available' : '✗ Not Found'}</p>
          </div>
        </div>

        {/* Отображаем информацию об объектах под изображением */}
        {imageFeatures && imageFeatures.length > 0 && (
          <div className="object-details">
            <h4>Detected Objects:</h4>
            {imageFeatures.map((obj, objIndex) => (
              <div key={objIndex} className="object-detail-item">
                <p><strong>Object {objIndex + 1}:</strong> {obj.name}</p>
                <p><strong>Location:</strong> {obj.location}</p>
                <p><strong>Size:</strong> {obj.size}</p>
                <p><strong>Bounding Box:</strong></p>
                <ul>
                  <li>x_min: {obj.bbox?.x_min}</li>
                  <li>y_min: {obj.bbox?.y_min}</li>
                  <li>x_max: {obj.bbox?.x_max}</li>
                  <li>y_max: {obj.bbox?.y_max}</li>
                </ul>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="App">
      <header className="App-header">
        <h1>Product Image Analyzer</h1>
        <div className="input-section">
          <input
            type="text"
            value={productId}
            onChange={(e) => setProductId(e.target.value)}
            onKeyPress={handleKeyPress}
            placeholder="Enter product ID"
            className="product-id-input"
          />
          <button 
            onClick={handleAnalyze} 
            disabled={loading}
            className="analyze-button"
          >
            {loading ? 'Analyzing...' : 'Analyze Product'}
          </button>
        </div>

        {error && <div className="error-message">{error}</div>}

        {results && (
          <div className="results-section">
            <h2>Analysis Results for Product {results.product_id}</h2>
            <p>Images processed: {results.images_processed}</p>

            <div className="images-grid">
              <h3>Product Images</h3>
              {results.imagesInfo?.images?.map((img, index) => {
                // Получаем данные для конкретного изображения
                const imageFeatures = results.features?.[index];
                return (
                  <ImageViewWithDetails
                    key={index}
                    imageInfo={img}
                    imageFeatures={imageFeatures}
                    index={index}
                  />
                );
              })}
            </div>

            <div className="analysis-results">
              <h3>Complete Object Analysis</h3>
              {results.features?.map((imageFeatures, imageIndex) => (
                <div key={imageIndex} className="image-analysis">
                  <h4>Image {imageIndex + 1} Detailed Analysis</h4>
                  {imageFeatures?.map((obj, objIndex) => (
                    <div key={objIndex} className="object-feature">
                      <h5>{obj.name}</h5>
                      <p><strong>Location:</strong> {obj.location}</p>
                      <p><strong>Size:</strong> {obj.size}</p>
                      <p><strong>Bounding Box Coordinates:</strong></p>
                      <ul>
                        <li>x_min: {obj.bbox?.x_min}</li>
                        <li>y_min: {obj.bbox?.y_min}</li>
                        <li>x_max: {obj.bbox?.x_max}</li>
                        <li>y_max: {obj.bbox?.y_max}</li>
                      </ul>
                    </div>
                  ))}
                </div>
              ))}
            </div>
          </div>
        )}
      </header>
    </div>
  );
}

export default App;
